    public static function svg(?string $name, string $class = 'ic', int $size = 24): string
    {
        $name = $name ?: 'sparkles';
        if (isset(self::BRANDS[$name])) {
            return '<svg class="'.e($class).'" width="'.$size.'" height="'.$size.'" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="'.self::BRANDS[$name].'"/></svg>';
        }
        $inner = self::OUTLINE[$name] ?? self::OUTLINE['sparkles'];
        return '<svg class="'.e($class).'" width="'.$size.'" height="'.$size.'" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'.$inner.'</svg>';
    }

    /** Icon names offered in the CMS for facilities / highlights. */
    public static function choices(): array
    {
        return array_combine(array_keys(self::OUTLINE), array_keys(self::OUTLINE));
    }
